/**
 * Browser half of @ds-hu/dsh-task-manager.
 *
 * Registers two slots on the Harness page:
 *  - `sidebar.panellist` → the left-sidebar entry (`任务管理器` / `Task Manager`);
 *  - `main` keyed `task-manager` → the full Win11-style panel.
 *
 * The bundle is generated by scripts/build-client.mjs; keep factories free of
 * side effects and put every registration inside `apply`.
 */
import { createElement, useEffect, useState, useSyncExternalStore } from 'react';
import { NS, dictionaries, en } from './i18n.js';

const PANEL_ID = 'task-manager';
const API_BASE = '/dsh-task-manager/api';

/** Services required by this client half. */
export const inject = ['slots', 'locale', 'theme'];

/**
 * Resolve a template string with `{name}` placeholders.
 * @param {string} template - Template.
 * @param {Record<string, string | number>} [vars] - Values.
 * @returns {string} the rendered text.
 */
function format(template, vars = {}) {
  return template.replace(/\{(\w+)\}/gu, (match, key) => (key in vars ? String(vars[key]) : match));
}

/**
 * Locale + dictionary store. `t` is stable and reads the live locale, which is
 * what the sidebar label thunk needs.
 * @param {any} ctx - Client context.
 * @returns {{ t: (key: string, vars?: Record<string, string | number>) => string, subscribe: (listener: () => void) => () => void, getSnapshot: () => string }} the i18n face.
 */
function createI18n(ctx) {
  let active = ctx.locale.getLocale().active;
  const listeners = new Set();
  const update = () => {
    const next = ctx.locale.getLocale().active;
    if (next === active) return;
    active = next;
    for (const listener of listeners) listener();
  };
  ctx.effect(() => ctx.locale.subscribe(update), 'task-manager: locale changes');

  const t = (key, vars) => {
    const dict = dictionaries[active] ?? dictionaries.en ?? en;
    const template = dict[key] ?? en[key] ?? key;
    return vars === undefined ? template : format(template, vars);
  };

  return {
    t,
    getSnapshot: () => active,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/**
 * Host theme store: `light` / `dark`, following `theme/change`.
 * @param {any} ctx - Client context.
 * @returns {{ getSnapshot: () => string, subscribe: (listener: () => void) => () => void }} the theme face.
 */
function createTheme(ctx) {
  let scheme = ctx.theme.getTheme().active.colorScheme;
  const listeners = new Set();
  const update = () => {
    const next = ctx.theme.getTheme().active.colorScheme;
    if (next === scheme) return;
    scheme = next;
    for (const listener of listeners) listener();
  };
  ctx.effect(() => ctx.on('theme/change', update), 'task-manager: theme changes');

  return {
    getSnapshot: () => scheme,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/**
 * JSON API client. Same origin, relative base, no token.
 * @param {string} [base] - API base.
 * @returns {{ get: (path: string, signal?: AbortSignal) => Promise<any>, post: (path: string, body: unknown) => Promise<any> }} the client.
 */
function createApi(base = API_BASE) {
  const parse = async (response) => {
    const payload = await response.json().catch(() => undefined);
    if (!response.ok || payload?.ok === false) {
      const error = new Error(payload?.error ?? `HTTP ${response.status}`);
      error.code = payload?.code ?? `http-${response.status}`;
      error.status = response.status;
      throw error;
    }
    return payload;
  };
  return {
    get: async (path, signal) => {
      const response = await fetch(`${base}${path}`, {
        signal,
        cache: 'no-store',
        headers: { accept: 'application/json' },
      });
      return parse(response);
    },
    post: async (path, body) => {
      const response = await fetch(`${base}${path}`, {
        method: 'POST',
        cache: 'no-store',
        headers: { 'content-type': 'application/json', accept: 'application/json' },
        body: JSON.stringify(body),
      });
      return parse(response);
    },
  };
}

/** Placeholder shell; the Win11 UI task replaces this component. */
function App(props) {
  const { i18n, theme } = props;
  const { t } = i18n;
  const scheme = useSyncExternalStore(theme.subscribe, theme.getSnapshot, theme.getSnapshot);
  const [health, setHealth] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();
    props.api
      .get('/health', controller.signal)
      .then((value) => {
        setHealth(value);
        setError(null);
      })
      .catch((reason) => {
        if (reason?.name !== 'AbortError') setError(reason?.message ?? String(reason));
      });
    return () => controller.abort();
  }, [props.api]);

  return createElement(
    'div',
    {
      className: 'tm-root',
      'data-theme': scheme,
      'data-testid': 'tm-root',
      style: {
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        minHeight: 0,
        padding: 24,
        boxSizing: 'border-box',
        background: scheme === 'dark' ? '#202020' : '#f3f3f3',
        color: scheme === 'dark' ? '#ffffff' : '#1b1b1b',
        fontFamily: '"Segoe UI Variable Text", "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif',
      },
    },
    createElement('h1', { style: { fontSize: 20, fontWeight: 600, margin: 0 } }, t('panel')),
    createElement(
      'p',
      { style: { fontSize: 13, opacity: 0.7 } },
      health === null
        ? error === null
          ? t('empty.loading')
          : `${t('empty.error')}: ${error}`
        : `Host v${health.version} · pid ${health.pid} · ${health.platform}`,
    ),
  );
}

/** Left-rail glyph: a monitor with a waveform, 18px, currentColor. */
function PanelIcon(props) {
  const size = props.size ?? 18;
  return createElement(
    'svg',
    {
      width: size,
      height: size,
      viewBox: '0 0 20 20',
      fill: 'none',
      stroke: 'currentColor',
      strokeWidth: 1.5,
      strokeLinecap: 'round',
      strokeLinejoin: 'round',
      'aria-hidden': true,
      focusable: false,
      style: { display: 'block' },
    },
    createElement('rect', { x: 2, y: 3, width: 16, height: 11, rx: 1.5 }),
    createElement('path', { d: 'M7 17h6M10 14v3' }),
    createElement('path', { d: 'M4.5 10.5l2-3 2 4 2.5-5 2 3 2-1.5' }),
  );
}

/**
 * Register both slots.
 * @param {any} ctx - Client context.
 * @returns {void}
 */
export function apply(ctx) {
  const i18n = createI18n(ctx);
  const theme = createTheme(ctx);
  const api = createApi();

  ctx.effect(() => ctx.locale.register(NS, dictionaries), 'task-manager: dictionaries');

  const injected = { api, i18n, theme };

  ctx.slots.inject('main', () =>
    ctx.slots.register(
      { name: 'main', key: PANEL_ID, locale: NS, inject: () => injected },
      App,
    ),
  );

  ctx.slots.inject('sidebar.panellist', () =>
    ctx.slots.register(
      {
        name: 'sidebar.panellist',
        id: PANEL_ID,
        order: 15,
        locale: NS,
        label: () => i18n.t('panel'),
      },
      PanelIcon,
    ),
  );
}
